// ----------------------------------------------------------------------
// --- parameters (mm) ---
flange_d = 200;           // flange outside diameter
flange_l = 200;           // flange length
flange_t = 5;             // flange thickness
hub_d = 18;               // hub diameter
hub_l = 12;               // hub length
bolt_d = 4.5;             // bolt hole diameter
